plist.dict:
CFBundlePackageType
APPL
CFBundleName
O.R.C.A.
CFBundleExecutable
{{.OutputFilename | html}}
CFBundleIdentifier
com.wails.{{.Name | html}}
CFBundleVersion
{{.Info.ProductVersion | html}}
CFBundleGetInfoString
{{.Info.Comments | html}}
CFBundleShortVersionString
{{.Info.ProductVersion | html}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable

NSHumanReadableCopyright
{{.Info.Copyright | html}}
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions
    {{.Ext | html}}
    CFBundleTypeName
    {{.Name | html}}
    CFBundleTypeRole
    {{.Role | html}}
    CFBundleTypeIconFile
    {{.IconName | html}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

    CFBundleURLName
    com.wails.{{.Scheme | html}}
    CFBundleURLSchemes
    {{.Scheme | html}}
    CFBundleTypeRole
    {{.Role | html}}

  {{end}}

{{end}}
